@Composable fun App(){val c=LocalContext.current;val p=remember{loadProfile(c)};var s by remember{mutableStateOf(loadScreen(c))};var ms by remember{mutableStateOf(loadMeasurements(c))};var ph by remember{mutableStateOf(loadPhotos(c))};LaunchedEffect(s,p.name,p.city,p.about,p.occupation,p.avatar,p.goal,p.age,p.height,p.weight,p.experience,p.days,p.place,p.health,ms,ph){save(c,p,s,ms,ph)};MaterialTheme(colorScheme=lightColorScheme(primary=Ink,background=Canvas,surface=Surface,onPrimary=Color.White,onBackground=Ink,onSurface=Ink)){androidx.compose.material3.Surface(Modifier.fillMaxSize(),color=Canvas){when(s){Screen.WELCOME->Page("Frost Fitness","Тренировки, питание и прогресс — в одном месте."){Hero("FF","Твой персональный фитнес-план вместе с Фростиком.");Primary("Настроить программу"){s=Screen.GOAL}};Screen.GOAL->Choice("Какая у тебя цель?",listOf("Снизить вес","Набрать мышцы","Стать сильнее","Поддерживать форму"),p.goal,{p.goal=it}){s=Screen.BASICS};Screen.BASICS->Page("О тебе","Эти данные нужны для персональной программы."){FieldNum("Возраст",p.age){p.age=it};FieldNum("Рост, см",p.height){p.height=it};FieldNum("Вес, кг",p.weight,true){p.weight=it};Primary(enabled=p.age.isNotBlank()&&p.height.isNotBlank()&&p.weight.isNotBlank()){s=Screen.EXP}};Screen.EXP->Choice("Опыт тренировок",listOf("Начинающий","До 1 года","1–3 года","Более 3 лет"),p.experience,{p.experience=it}){s=Screen.DAYS};Screen.DAYS->Page("Ритм тренировок","Сколько раз в неделю тебе удобно заниматься?"){Segment((2..5).map{it.toString()},p.days.toString()){p.days=it.toInt()};Primary(){s=Screen.PLACE}};Screen.PLACE->Choice("Где тренируемся?",listOf("Зал","Дом: гантели","Дом: без оборудования"),p.place,{p.place=it}){s=Screen.HEALTH};Screen.HEALTH->Page("Здоровье","Укажи ограничения, которые важно учитывать."){Field("Ограничения и противопоказания",p.health,4){p.health=it};Primary("Создать программу",p.health.isNotBlank()){s=Screen.HOME}};Screen.HOME->Home(p){s=Screen.PROFILE};Screen.PROFILE->ProfilePage(p,