@Composable fun Home(p:Profile,profile:()->Unit){Page(if(p.name.isBlank())"Сегодня" else "Привет, ${p.name}","${p.goal} · ${p.days} тренировки в неделю"){Hero("Ф","Фростик рядом. Сегодня двигаемся по твоему плану.");CardBlock{Text("Сегодня",fontSize=13.sp,color=Secondary);Text("Тренировка всего тела",fontSize=22.sp,fontWeight=FontWeight.Bold);Text("45 мин · 6 упражнений",color=Secondary);Spacer(Modifier.height(10.dp));Primary("Начать тренировку"){} };Text("Твой прогресс",fontSize=22.sp,fontWeight=FontWeight.Bold);Row(horizontalArrangement=Arrangement.spacedBy(10.dp)){Stat("0","тренировок",Modifier.weight(1f));Stat(p.weight.ifBlank{"—"},"кг",Modifier.weight(1f))};SecondaryButton("Мой профиль и замеры",profile)}}
@Composable fun ProfilePage(p:Profile,ms:List<Measurement>,addM:(Measurement)->Unit,ph:List<ProgressPhotos>,addP:(ProgressPhotos)->Unit,back:()->Unit){var tab by remember{mutableIntStateOf(0)};Page("Профиль",p.name.ifBlank{"Персональные данные и прогресс"}){val tabs=listOf("Профиль","Замеры","Фото");Segment(tabs,tabs[tab]){tab=tabs.indexOf(it)};when(tab){0->ProfileFields(p);1->Measurements(ms,addM);2->PhotoProgress(ph,addP)};SecondaryButton("Готово",back)}}
@Composable fun ProfileFields(p:Profile){val c=LocalContext.current;val pick=rememberLauncherForActivityResult(ActivityResultContracts.OpenDocument()){u:Uri?->u?.let{runCatching{c.contentResolver.takePersistableUriPermission(it,android.content.Intent.FLAG_GRANT_READ_URI_PERMISSION)};p.avatar=it.toString()}};Column(horizontalAlignment=Alignment.CenterHorizontally,modifier=Modifier.fillMaxWidth()){Box(Modifier.size(104.dp).clip(CircleShape).background(Color(0xFFE9E9ED)),contentAlignment=Alignment.Center){Text(if(p.avatar.isBlank())"Ф" else "✓",fontSize=34.sp,fontWeight=FontWeight.Bold)};TextButton({pick.launch(arrayOf("image/*"))}){Text(if(p.avatar.isBlank())"Добавить фото" else "Изменить фото")}};Section("Основное"){Field("Имя",p.name){p.name=it};Field("Город",p.city){p.city=it};Field("Род деятельности",p.occupation){p.occupation=it};Field("О себе",p.about,4){p.about=it}};Section("Физические данные"){FieldNum("Возраст",p.age){p.age=it};FieldNum("Рост, см",p.height){p.height=it};FieldNum("Вес, кг",p.weight,true){p.weight=it}};Section("Тренировки"){Field("Стаж",p.experience){p.experience=it};Field("Цель",p.goal){p.goal=it};Field("Место тренировок",p.place){p.place=it};Field("Ограничения здоровья",p.health,3){p.health=it}};Text("Все изменения сохраняются автоматически.",color=Secondary,fontSize=13.sp)}
@Composable fun Measurements(items:List<Measurement>,add:(Measurement)->Unit){val labels=listOf("Вес","Шея","Плечи","Грудь","Талия","Живот","Бёдра","Бицепс левый","Бицепс правый","Предплечье левое","Предплечье правое","Бедро левое","Бедро правое","Икра левая","Икра правая");val v=remember{mutableStateMapOf<String,String>()};Section("Новый замер"){labels.forEach{l->FieldNum(if(l=="Вес")"$l, кг" else "$l, см",v[l]?:"",true){v[l]=it}}};Primary("Сохранить замер",v.values.any{it.isNotBlank()}){add(Measurement(LocalDate.now().toString(),v.toMap()));v.clear()};if(items.isNotEmpty()){Text("История",fontSize=22.sp,fontWeight=FontWeight.Bold);items.asReversed().forEach{m->CardBlock{Text(m.date,fontWeight=FontWeight.SemiBold);Text(m.values.filterValues{it.isNotBlank()}.entries.joinToString(" · "){"${it.key} ${it.value}"},color=Secondary)}}}}
@Composable fun PhotoProgress(items:List<ProgressPhotos>,add:(ProgressPhotos)->Unit){val c=LocalContext.current;var front by remember{mutableStateOf("")};var side by remember{mutableStateOf("")};var back by remember{mutableStateOf("")};fun keep(u:Uri?):String{if(u==null)return "";runCatching{c.contentResolver.takePersistableUriPermission(u,android.content.Intent.FLAG_GRANT_READ_URI_PERMISSION)};return u.toString()};val f=rememberLauncherForActivityResult(ActivityResultContracts.OpenDocument()){front=keep(it)};val s=rememberLauncherForActivityResult(ActivityResultContracts.OpenDocument()){side=keep(it)};val b=rememberLauncherForActivityResult(ActivityResultContracts.OpenDocument()){back=keep(it)};Hero("AI","Снимай прогресс в одинаковом свете и с одного расстояния. Позже ИИ сможет сравнивать изменения.");Section("Новая серия"){PhotoRow("Спереди",front.isNotBlank()){f.launch(arrayOf("image/*"))};PhotoRow("Сбоку",side.isNotBlank()){s.launch(arrayOf("image/*"))};PhotoRow("Сзади",back.isNotBlank()){b.launch(arrayOf("image/*"))}};Primary("Сохранить серию",front.isNotBlank()||side.isNotBlank()||back.isNotBlank()){add(ProgressPhotos(LocalDate.now().toString(),front,side,back));front="";side="";back=""};if(items.isNotEmpty()){Text("История фото",fontSize=22.sp,fontWeight=FontWeight.Bold);items.asReversed().forEach{CardBlock{Text(it.date,fontWeight=FontWeight.SemiBold);Text("Спереди ${if(it.front.isBlank())"—" else "✓"}   Сбоку ${if(it.side.isBlank())"—" else "✓"}   Сзади ${if(it.back.isBlank())"—" else "✓"}",color=Secondary)}}}}
@Composable fun Page(title:String,sub:String="",body:@Composable ColumnScope.()->Unit){Column(Modifier.fillMaxSize().verticalScroll(rememberScrollState()).statusBarsPadding().navigationBarsPadding().padding(horizontal=20.dp),verticalArrangement=Arrangement.spacedBy(14.dp)){Spacer(Modifier.height(12.dp));Text("FROST FITNESS",fontSize=12.sp,fontWeight=FontWeight.Bold,color=Secondary);Text(title,fontSize=34.sp,fontWeight=FontWeight.Bold,letterSpacing=(-1).sp);if(sub.isNotBlank())Text(sub,color=Secondary,fontSize=16.sp);Spacer(Modifier.height(2.dp));body();Spacer(Modifier.height(28.dp))}}
