@Composable fun Field(label:String,value:String,lines:Int=1,set:(String)->Unit){OutlinedTextField(value,set,label={Text(label)},singleLine=lines==1,minLines=lines,shape=RoundedCornerShape(14.dp),colors=OutlinedTextFieldDefaults.colors(unfocusedBorderColor=Line,focusedBorderColor=Ink,unfocusedContainerColor=Surface,focusedContainerColor=Surface),modifier=Modifier.fillMaxWidth().padding(vertical=3.dp))}
