fun prefs(c:android.content.Context)=c.getSharedPreferences("frost_fitness",android.content.Context.MODE_PRIVATE)
fun loadProfile(c:android.content.Context)=Profile().apply{val x=prefs(c);name=x.getString("name","")!!;city=x.getString("city","")!!;about=x.getString("about","")!!;occupation=x.getString("occupation","")!!;avatar=x.getString("avatar","")!!;goal=x.getString("goal","")!!;age=x.getString("age","")!!;height=x.getString("height","")!!;weight=x.getString("weight","")!!;experience=x.getString("experience","")!!;days=x.getInt("days",3);place=x.getString("place","Зал")!!;health=x.getString("health","")!!}
fun loadScreen(c:android.content.Context)=runCatching{Screen.valueOf(prefs(c).getString("screen","WELCOME")!!)}.getOrDefault(Screen.WELCOME)
fun esc(s:String)=android.util.Base64.encodeToString(s.toByteArray(),android.util.Base64.NO_WRAP);fun unesc(s:String)=runCatching{String(android.util.Base64.decode(s,android.util.Base64.NO_WRAP))}.getOrDefault("")
fun save(c:android.content.Context,p:Profile,s:Screen,m:List<Measurement>,ph:List<ProgressPhotos>){prefs(c).edit().putString("name",p.name).putString("city",p.city).putString("about",p.about).putString("occupation",p.occupation).putString("avatar",p.avatar).putString("goal",p.goal).putString("age",p.age).putString("height",p.height).putString("weight",p.weight).putString("experience",p.experience).putInt("days",p.days).putString("place",p.place).putString("health",p.health).putString("screen",s.name).putString("measurements",m.joinToString(";"){esc(it.date)+","+esc(it.values.entries.joinToString("|"){e->e.key+"="+e.value})}).putString("photos",ph.joinToString(";"){listOf(it.date,it.front,it.side,it.back).joinToString(","){v->esc(v)}}).apply()}
fun loadMeasurements(c:android.content.Context):List<Measurement>{val raw=prefs(c).getString("measurements","")?:"";if(raw.isBlank())return emptyList();return raw.split(';').mapNotNull{r->val q=r.split(',',limit=2);if(q.size<2)null else Measurement(unesc(q[0]),unesc(q[1]).split('|').mapNotNull{e->val z=e.split('=',limit=2);if(z.size==2)z[0] to z[1] else null}.toMap())}}
fun loadPhotos(c:android.content.Context):List<ProgressPhotos>{val raw=prefs(c).getString("photos","")?:"";if(raw.isBlank())return emptyList();return raw.split(';').mapNotNull{r->val q=r.split(',');if(q.size==4)ProgressPhotos(unesc(q[0]),unesc(q[1]),unesc(q[2]),unesc(q[3]))else null}}